{"content":"1|//! Global native-name allocation. Never infer a counter from provider names.
2|//! A committed intent is a permanent fence until exact readback is published.
3|use super::*;
4|
5|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
6|#[serde(deny_unknown_fields)]
7|pub struct NativeCreationRequest {
8|    pub operation_id: String,
9|    pub actor_id: String,
10|    pub caller_session: String,
11|    pub caller_genesis: String,
12|    pub owner_kind: String,
13|    pub logical_target: String,
14|    pub request_digest: String,
15|    pub request_json: String,
16|}
17|
18|#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
19|#[serde(deny_unknown_fields)]
20|pub struct NativeCreationRecord {
21|    pub request: NativeCreationRequest,
22|    pub number: i64,
23|    pub name: String,
24|    pub phase: String,
25|    pub native_uuid: String,
26|}
27|
28|pub fn is_numbered_native_name(name: &str) -> bool {
29|    name.strip_prefix("ID-").is_some_and(|number| {
30|        number.parse::<i64>().is_ok_and(|n| n > 0 && n.to_string() == number)
31|    })
32|}
33|
34|fn records(tx: &MultiTransaction) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
35|    query(tx, "?[document] := *native_container_creations{document}", Params::new())?
36|        .rows.iter().map(|row| {
37|            let record: NativeCreationRecord = serde_json::from_str(&string(row, 0)?)?;
38|            if record.number <= 0 || record.name != format!("ID-{}", record.number)
39|                || !matches!(record.phase.as_str(), "intent" | "bound" | "complete")
40|                || (record.phase != "intent" && uuid::Uuid::parse_str(&record.native_uuid)
41|                    .map_or(true, |id| id.to_string() != record.native_uuid))
42|            {
43|                return Err(err("native creation journal is corrupt"));
44|            }
45|            Ok(record)
46|        }).collect()
47|}
48|
49|pub(super) fn binding_in_tx(tx: &MultiTransaction, name: &str)
50|    -> std::result::Result<Option<NativeCreationRecord>, CozoError>
51|{
52|    let mut found = records(tx)?.into_iter().filter(|row| row.name == name);
53|    let result = found.next();
54|    if found.next().is_some() { return Err(err("duplicate native name binding")); }
55|    Ok(result)
56|}
57|
58|fn put(tx: &MultiTransaction, record: &NativeCreationRecord) -> std::result::Result<(), CozoError> {
59|    query(tx, "?[operation_id,document] <- [[$op,$doc]] :put native_container_creations {operation_id => document}",
60|        BTreeMap::from([
61|            ("op".into(), DataValue::Str(record.request.operation_id.as_str().into())),
62|            ("doc".into(), DataValue::Str(serde_json::to_string(record)?.into())),
63|        ]))?;
64|    Ok(())
65|}
66|
67|fn sequence(tx: &MultiTransaction, rows: &[NativeCreationRecord])
68|    -> std::result::Result<(i64, String), CozoError>
69|{
70|    let result = query(tx, "?[next,pending] := *native_container_sequence{key,next,pending}, key = 'default'", Params::new())?;
71|    let (next, pending) = match result.rows.as_slice() {
72|        [] if rows.is_empty() => {
73|            let marker = query(tx, "?[completed] := *schema_migrations{name,completed}, name = 'native-container-sequence-v1'", Params::new())?;
74|            if !marker.rows.is_empty() { return Err(err("native creation sequence is missing; refusing reset")); }
75|            (1, String::new())
76|        }
77|        [row] => (integer(row, 0)?, string(row, 1)?),
78|        _ => return Err(err("native creation sequence is missing or corrupt")),
79|    };
80|    let mut sorted = rows.iter().collect::<Vec<_>>();
81|    sorted.sort_by_key(|r| r.number);
82|    let mut expected = 1i64;
83|    for row in sorted {
84|        if row.number != expected
85|            || (row.number < next && row.phase != "complete")
86|            || (row.number == next && (row.phase == "complete" || row.request.operation_id != pending))
87|            || row.number > next
88|        { return Err(err("native creation history is incomplete; refusing sequence recovery")); }
89|        expected = expected.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
90|    }
91|    if next < 1 || (pending.is_empty() && expected != next)
92|        || (!pending.is_empty() && next.checked_add(1) != Some(expected))
93|    { return Err(err("native sequence and pending fence disagree")); }
94|    Ok((next, pending))
95|}
96|
97|fn put_sequence(tx: &MultiTransaction, next: i64, pending: &str) -> std::result::Result<(), CozoError> {
98|    query(tx, "?[key,next,pending] <- [['default',$next,$pending]] :put native_container_sequence {key => next,pending}",
99|        BTreeMap::from([("next".into(), dv_int(next)), ("pending".into(), DataValue::Str(pending.into()))]))?;
100|    query(tx, "?[name,completed] <- [['native-container-sequence-v1',true]] :put schema_migrations {name => completed}", Params::new())?;
101|    Ok(())
102|}
103|
104|impl CozoGraphShuttle {
105|    pub fn native_creation_records(&self) -> std::result::Result<Vec<NativeCreationRecord>, CozoError> {
106|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
107|        let tx = self.db.multi_transaction(false);
108|        let rows = records(&tx)?;
109|        sequence(&tx, &rows)?;
110|        commit_checked(&tx)?;
111|        Ok(rows)
112|    }
113|
114|    /// `fresh` is the only permission to issue POST, returned after the barrier.
115|    /// Replays, including intent-only replays, may only read/reconcile.
116|    pub fn reserve_native_creation(&self, request: NativeCreationRequest, observed_names: &[String])
117|        -> std::result::Result<(NativeCreationRecord, bool), CozoError>
118|    {
119|        if self.identity_directory.is_none() { return Err(err("native allocation requires persistent Cozo")); }
120|        if uuid::Uuid::parse_str(&request.operation_id).map_or(true, |id| id.to_string() != request.operation_id)
121|            || request.actor_id.is_empty() || request.caller_session.is_empty() || request.caller_genesis.is_empty()
122|            || !matches!(request.owner_kind.as_str(), "identity" | "project" | "incus")
123|            || request.logical_target.is_empty() || !valid_root_repair_digest(&request.request_digest)
124|            || request.request_json.len() > 65536
125|        { return Err(err("invalid native creation intent")); }
126|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
127|        self.sync_identity_store()?;
128|        let tx = self.db.multi_transaction(true);
129|        let rows = records(&tx)?;
130|        let (next, pending) = sequence(&tx, &rows)?;
131|        for name in observed_names.iter().filter(|n| n.starts_with("ID-")) {
132|            if !rows.iter().any(|row| &row.name == name) {
133|                return Err(err("untracked ID-N native name; refusing allocation or max+1 recovery"));
134|            }
135|        }
136|        if let Some(row) = rows.iter().find(|row| row.request.operation_id == request.operation_id) {
137|            if row.request != request { return Err(err("native operation_id reused with different caller or request")); }
138|            commit_checked(&tx)?;
139|            return Ok((row.clone(), false));
140|        }
141|        if !pending.is_empty() { return Err(err("native creation unresolved; reconcile the owning operation before allocating another name")); }
142|        if request.owner_kind != "incus" && rows.iter().any(|row| row.request.owner_kind == request.owner_kind
143|            && row.request.logical_target == request.logical_target && observed_names.contains(&row.name))
144|        { return Err(err("logical target already has a native container; retain its binding")); }
145|        next.checked_add(1).ok_or_else(|| err("native name sequence exhausted"))?;
146|        let record = NativeCreationRecord { request, number: next, name: format!("ID-{next}"), phase: "intent".into(), native_uuid: String::new() };
147|        if observed_names.contains(&record.name) { return Err(err("native name collision")); }
148|        put(&tx, &record)?;
149|        put_sequence(&tx, next, &record.request.operation_id)?;
150|        commit_checked(&tx)?;
151|        self.sync_identity_store()?;
152|        Ok((record, true))
153|    }
154|
155|    pub fn bind_native_creation(&self, expected: &NativeCreationRecord, native_uuid: &str)
156|        -> std::result::Result<NativeCreationRecord, CozoError>
157|    {
158|        if uuid::Uuid::parse_str(native_uuid).map_or(true, |id| id.to_string() != native_uuid) {
159|            return Err(err("native creation readback lacks canonical UUID"));
160|        }
161|        self.update_native_creation(expected, native_uuid, false)
162|    }
163|
164|    /// Called only after complete canonical SHM publication. No abort/reset API.
165|    pub fn complete_native_creation(&self, expected: &NativeCreationRecord)
166|        -> std::result::Result<NativeCreationRecord, CozoError>
167|    {
168|        self.update_native_creation(expected, &expected.native_uuid, true)
169|    }
170|
171|    fn update_native_creation(&self, expected: &NativeCreationRecord, native_uuid: &str, complete: bool)
172|        -> std::result::Result<NativeCreationRecord, CozoError>
173|    {
174|        let _guard = self.identity_transaction.lock().map_err(|_| err("identity transaction owner is poisoned"))?;
175|        let tx = self.db.multi_transaction(true);
176|        let rows = records(&tx)?;
177|        let (next, pending) = sequence(&tx, &rows)?;
178|        let current = rows.iter().find(|r| r.request.operation_id == expected.request.operation_id)
179|            .ok_or_else(|| err("native creation intent disappeared"))?;
180|        if current != expected { return Err(err("native creation compare/exchange conflict")); }
181|        if current.phase == "complete" {
182|            if current.native_uuid != native_uuid { return Err(err("native UUID changed")); }
183|            commit_checked(&tx)?;
184|            self.sync_identity_store()?;
185|            return Ok(current.clone());
186|        }
187|        if pending != current.request.operation_id || next != current.number
188|            || (!current.native_uuid.is_empty() && current.native_uuid != native_uuid)
189|            || (complete && current.phase != "bound")
190|        { return Err(err("native creation fence or UUID changed")); }
191|        let mut updated = current.clone();
192|        updated.native_uuid = native_uuid.into();
193|        updated.phase = if complete { "complete" } else { "bound" }.into();
194|        put(&tx, &updated)?;
195|        if complete { put_sequence(&tx, next.checked_add(1).ok_or_else(|| err("native sequence exhausted"))?, "")?; }
196|        commit_checked(&tx)?;
197|        self.sync_identity_store()?;
198|        Ok(updated)
199|    }
