423|async fn resolve_context(
424|    engine: &MutationEngine,
425|    session: &str,
426|    grants: &BTreeSet<String>,
427|    input: ResolveContextInput,
428|) -> Result<ResolvedChatContext> {
429|    if input.mode != ChatMode::Project && input.project_id.is_some() {
430|        bail!("project_id is only valid in project mode");
431|    }
432|    if input.mode != ChatMode::Personal && input.personal_namespace.is_some() {
433|        bail!("personal_namespace is only valid in personal mode");
434|    }
435|    let mut context = ResolvedChatContext {
436|        mode: input.mode,
437|        session_id: session.into(),
438|        project_id: None,
439|        memory_namespace: String::new(),
440|        read_only: input.mode == ChatMode::Accountability,
441|        effective_capabilities: BTreeSet::new(),
442|        allowed_agents: BTreeSet::new(),
443|        selected_agent: None,
444|    };
445|    match input.mode {
446|        ChatMode::Project => {
447|            let id = input
448|                .project_id
449|                .ok_or_else(|| anyhow!("project mode requires project_id"))?;
450|            let project = get_project(engine, &id).await?;
451|            context.effective_capabilities = project.effective_capabilities(session, grants)?;
452|            require_ready(&project).await?;
453|            context.read_only = project.role_for(session) == Some(ProjectRole::Reader);
454|            context.memory_namespace = format!("project/{id}");
455|            context.project_id = Some(id);
456|            context.allowed_agents = project.allowed_agents;
457|            context.selected_agent = project.selected_agent;
458|        }
459|        ChatMode::Personal => {
460|            context.memory_namespace = memory_namespace_for(
461|                ChatMode::Personal,
462|                session,
463|                None,
464|                input.personal_namespace.as_deref(),
465|            )?;
466|            context.effective_capabilities = grants
467|                .iter()
468|                .filter(|cap| {
469|                    matches!(
470|                        cap.as_str(),
471|                        "chat.context" | "cognitive.read" | "cognitive.memory.write"
472|                    )
473|                })
474|                .cloned()
475|                .collect();
476|        }
477|        ChatMode::ControlPlane => {
478|            if !grants.contains("chat.control_plane") {
479|                bail!("control-plane mode requires an explicit grant");
480|            }
481|            context.memory_namespace = format!("session/{session}/control_plane");
482|            context.effective_capabilities = grants
483|                .iter()
484|                .filter(|cap| {
485|                    matches!(
486|                        cap.as_str(),
487|                        "chat.context"
488|                            | "cognitive.read"
489|                            | "cognitive.memory.write"
490|                            | "workflows.read"
491|                            | "workflows.execute"
492|                    )
493|                })
494|                .cloned()
495|                .collect();
496|        }
497|        ChatMode::Accountability => {
498|            context.memory_namespace = format!("session/{session}/accountability");
499|            context.effective_capabilities = grants
500|                .iter()
501|                .filter(|cap| matches!(cap.as_str(), "chat.context" | "snowball.read"))
502|                .cloned()
503|                .collect();
504|        }
505|        ChatMode::NotebookLm => {
506|            // The partition is the notebook this session selected through the
507|            // notebooklm plugin; none selected → the mode cannot be entered.
508|            let notebook = selected_notebook(engine, session)
509|                .await?
510|                .ok_or_else(|| anyhow!("notebooklm mode requires a selected notebook"))?;
511|            context.memory_namespace =
512|                memory_namespace_for(ChatMode::NotebookLm, session, Some(&notebook), None)?;
513|            context.effective_capabilities = grants
514|                .iter()
515|                .filter(|cap| {
516|                    matches!(
517|                        cap.as_str(),
518|                        "chat.context"
519|                            | "cognitive.read"
520|                            | "cognitive.memory.write"
521|                            | "notebooklm.read"
522|                            | "notebooklm.query"
523|                    )
524|                })
525|                .cloned()
526|                .collect();
527|        }
528|        ChatMode::UiRender => {
529|            // No memory at all: nothing recalled, nothing written.
530|            context.memory_namespace = String::new();
531|            context.read_only = true;
532|            context.effective_capabilities = grants
533|                .iter()
534|                .filter(|cap| matches!(cap.as_str(), "chat.context"))
535|                .cloned()
536|                .collect();
537|        }
538|    }
539|    Ok(context)
540|}
