577|pub(crate) async fn stored_selection(
578|    engine: &MutationEngine,
579|    session: &str,
580|) -> Result<ChatContextSelection> {
581|    let rows = catalog(
582|        engine,
583|        "?[document] := *chat_context_selection{session_id, document}, session_id = $session",
584|        json!({"session": session}),
585|    )
586|    .await?;
587|    let Some(document) = rows
588|        .as_array()
589|        .and_then(|rows| rows.first())
590|        .and_then(|row| row["document"].as_str())
591|    else {
592|        return Ok(ChatContextSelection::default());
593|    };
594|    Ok(serde_json::from_str(document)?)
