597|/// What this session's memory calls and turns bind to right now. Re-resolved
598|/// on every use so a revoked membership or grant takes effect immediately;
599|/// a selection that no longer resolves fails closed (no silent fallback to
600|/// personal).
601|pub(crate) async fn current_chat_context(
602|    engine: &MutationEngine,
603|    session: &str,
604|    grants: &BTreeSet<String>,
605|) -> Result<ResolvedChatContext> {
606|    let selection = stored_selection(engine, session).await?;
607|    resolve_selection(engine, session, grants, &selection).await
