381|    /// Existence and ownership are checked before project data access, including
382|    /// parked containers. A stale catalog row is not a substitute for a container.
383|    pub async fn verify_project_container(
384|        project_id: &str,
385|        instance_name: &str,
386|        owner: &str,
387|        persist_path: &str,
388|    ) -> Result<()> {
389|        if uuid::Uuid::parse_str(project_id)?.to_string() != project_id {
390|            anyhow::bail!("invalid project container id");
391|        }
392|        instance_path(instance_name)?;
393|        let value = serde_json::to_value(Self::incus_get_instance(instance_name).await?)?;
394|        if value["type"] != "container"
395|            || value["config"]["user.opdbus.project_id"] != project_id
396|            || value["config"]["user.opdbus.owner_session_id"] != owner
397|            || value["config"]["user.opdbus.role"] != "project"
398|            || value["devices"]["project"]["source"] != persist_path
399|            || value["devices"]["project"]["path"] != "/project"
400|            || value["devices"]["project"]["readonly"] != "true"
401|            || value["config"]["security.privileged"] != "false"
402|            || value["config"]["security.nesting"] != "false"
403|        {
404|            anyhow::bail!("project container binding does not match its catalog");
405|        }
406|        Ok(())
407|    }
