409|    /// Update instance configuration via REST API (removes read-only fields first)
410|    async fn incus_update_instance(name: &str, mut config: simd_json::OwnedValue) -> Result<()> {
411|        if let Some(obj) = config.as_object_mut() {
412|            obj.retain(|k, _| !k.starts_with("volatile.") && !k.starts_with("image."));
413|        }
414|        let body = simd_json::to_string(&config)?;
415|        Self::incus_api_call("PUT", &format!("/1.0/instances/{}", name), Some(&body)).await?;
416|        Ok(())
417|    }
