419|    /// Run an incus operation via REST API (AGENTS.md §4: no subprocess bypasses)
420|    async fn run_incus_command(args: &[&str]) -> Result<Vec<u8>> {
421|        match args {
422|            ["list", "--format=json"] => {
423|                Self::incus_api_call("GET", "/1.0/instances?recursion=1", None).await
424|            }
425|            ["init", ..] => {
426|                let mut image = "";
427|                let mut name = "";
428|                let mut storage_pool = None;
429|                let mut profiles: Vec<String> = Vec::new();
430|                let mut no_profiles = false;
431|                let mut instance_type = "container";
432|                let mut i = 1;
433|                while i < args.len() {
434|                    match args[i] {
435|                        "--storage" => {
436|                            i += 1;
437|                            storage_pool = args.get(i).copied().map(String::from);
438|                        }
439|                        "--no-profiles" => {
440|                            no_profiles = true;
441|                        }
442|                        "--vm" => {
443|                            instance_type = "virtual-machine";
444|                        }
445|                        "--profile" => {
446|                            i += 1;
447|                            if let Some(p) = args.get(i) {
448|                                profiles.push(p.to_string());
449|                            }
450|                        }
451|                        arg if arg.starts_with('-') => {}
452|                        arg if image.is_empty() => image = arg,
453|                        arg if name.is_empty() => name = arg,
454|                        _ => {}
455|                    }
456|                    i += 1;
457|                }
458|
459|                let mut body = simd_json::json!({
460|                    "name": name,
461|                    "source": { "type": "image", "alias": image },
462|                    "type": instance_type,
463|                });
464|                if no_profiles {
465|                    body.insert("profiles", Value::Array(Vec::new()))?;
466|                } else if !profiles.is_empty() {
467|                    let profile_values: Vec<Value> =
468|                        profiles.iter().map(|p| Value::from(p.as_str())).collect();
469|                    body.insert("profiles", Value::Array(profile_values))?;
470|                }
471|                if let Some(pool) = storage_pool {
472|                    body.insert(
