475|                            "root": {
476|                                "type": "disk",
477|                                "pool": pool,
478|                                "path": "/"
479|                            }
480|                        }),
481|                    )?;
482|                }
483|                let body_str = simd_json::to_string(&body)?;
484|                Self::incus_api_call("POST", "/1.0/instances", Some(&body_str)).await
485|            }
486|            ["delete", name, "--force"] => {
487|                Ok(serde_json::to_vec(&IncusApi::local().delete(name).await?)?)
488|            }
