48|/// Caller holds lifecycle (if applicable), then host observation lock. The
49|/// durable intent is committed and flushed before the sole POST permission.
50|pub(crate) async fn create_locked(engine: &MutationEngine, request: NativeCreationRequest)
51|    -> Result<(NativeCreationRecord, bool)> {
52|    admit(engine, &request).await?;
53|    let native = IncusRootRepairBackend::local();
54|    let before = native.default_project_state().await?;
55|    let names = before.instances.iter().map(|i| i.name.clone()).collect::<Vec<_>>();
56|    let cozo = engine.identity_sled_store()?.cozo().clone();
57|    let (record, fresh) = tokio::task::spawn_blocking(move || cozo.reserve_native_creation(request, &names)).await??;
58|    // Any failure from here retains the fence, including definite provider
59|    // errors. An absent object is not proof that an earlier POST was rejected.
60|    if fresh {
61|        admit(engine, &record.request).await?;
62|        let mut body: Value = serde_json::from_str(&record.request.request_json)?;
63|        body["name"] = record.name.clone().into();
64|        body["config"]["user.opdbus.creation_operation"] = record.request.operation_id.clone().into();
65|        body["config"]["user.opdbus.creation_digest"] = record.request.request_digest.clone().into();
66|        incus::create_reserved_native(&body).await
67|            .context("native POST outcome requires reconciliation; reservation retained")?;
68|    }
69|    let record = reconcile_locked(engine, record).await?;
70|    Ok((record, !fresh))
71|}
