73|pub(crate) async fn reconcile_locked(engine: &MutationEngine, record: NativeCreationRecord)
74|    -> Result<NativeCreationRecord> {
75|    admit(engine, &record.request).await?;
76|    let native = IncusRootRepairBackend::local();
77|    let (raw, _) = native.instance(&record.name).await
78|        .context("reserved native instance absent or unreadable; POST will not be repeated")?;
79|    let body: Value = serde_json::from_str(&record.request.request_json)?;
80|    ensure!(raw["name"] == record.name && raw["type"] == body["type"]
81|        && raw["config"]["user.opdbus.creation_operation"] == record.request.operation_id
82|        && raw["config"]["user.opdbus.creation_digest"] == record.request.request_digest,
83|        "native creation ownership markers differ");
84|    if record.phase != "complete" {
85|        ensure!(raw["status"] == "Stopped" && raw["status_code"] == 102
86|            && raw["profiles"] == body["profiles"] && raw["devices"] == body["devices"],
87|            "native preparation is not the pinned stopped definition");
88|        if record.request.owner_kind == "identity" {
89|            ensure!(raw["expanded_config"]["security.privileged"] == "false"
90|                && raw["expanded_config"]["security.nesting"] == "false"
91|                && raw["expanded_config"]["boot.autostart"] == "false"
92|                && raw["expanded_config"]["raw.lxc"] == body["config"]["raw.lxc"],
93|                "expanded native identity security differs");
94|            let expanded = raw["expanded_devices"].as_object().context("expanded devices absent")?;
95|            ensure!(expanded.len() == 3 && expanded.get("root") == body["devices"].get("root")
96|                && expanded.get("runtime-run") == body["devices"].get("runtime-run")
97|                && expanded.get("lungs-socket-dir") == Some(&json!({"type":"disk", "source":"/run/opdbus/lungs",
98|                    "path":"/run/opdbus/lungs", "readonly":"true"})), "expanded identity devices differ");
99|        }
100|        for (key, value) in body["config"].as_object().context("creation config missing")? {
101|            ensure!(raw["config"].get(key) == Some(value), "native creation config differs");
102|        }
103|    }
104|    let native_uuid = raw["config"]["volatile.uuid"].as_str().context("native UUID absent")?.to_owned();
105|    ensure!(uuid::Uuid::parse_str(&native_uuid)?.to_string() == native_uuid, "noncanonical native UUID");
106|    let cozo = engine.identity_sled_store()?.cozo().clone();
107|    let pinned = record.clone();
108|    let bound = tokio::task::spawn_blocking(move || cozo.bind_native_creation(&pinned, &native_uuid)).await??;
109|    let snapshot = native.default_project_state().await?;
110|    let instance = snapshot.instances.iter().find(|i| i.name == bound.name)
111|        .context("created instance missing from full readback")?;
112|    ensure!(serde_json::to_value(instance)? == serde_json::to_value(incus::IncusPlugin::instance_from_native_metadata(raw)?)?,
113|        "native instance changed during full readback");
114|    crate::incus_observer::publish_repair_readback_locked(engine, &snapshot).await?;
115|    let cozo = engine.identity_sled_store()?.cozo().clone();
116|    Ok(tokio::task::spawn_blocking(move || cozo.complete_native_creation(&bound)).await??)
117|}
