119|pub(crate) async fn dispatch(engine: &MutationEngine, method: &str, args: &Value,
120|    actor: &str, session: Option<&str>, genesis: Option<&str>) -> Result<Value> {
121|    let session = session.context("native creation requires verified session")?.to_owned();
122|    let genesis = genesis.context("native creation requires verified genesis")?.to_owned();
123|    let engine = engine.clone();
124|    let method = method.to_owned();
125|    let args = args.clone();
126|    let actor = actor.to_owned();
127|    tokio::spawn(async move {
128|        let _host = engine.lock_host_observation().await;
129|        let (record, replayed) = if method == "create_instance" {
130|            let input: incus::CreateInstanceInput = serde_json::from_value(args)?;
131|            let body = incus::native_creation_body(&input)?;
132|            let request = request(&input.operation_id, &actor, &session, &genesis,
133|                "incus", &input.operation_id, body)?;
134|            create_locked(&engine, request).await?
135|        } else {
136|            let input: incus::ReconcileNativeCreationInput = serde_json::from_value(args)?;
137|            let record = records(&engine).await?.into_iter()
